class Solution:
    def isPalindrome(self, x: int) -> bool:
        # 负数的负号只在最左边，倒过来读不同，直接排除
        if x < 0:
            return False
        s = str(x)
        # 只需比较前一半与后一半的对称位置，mid 就是需要比较的次数
        mid = len(s) // 2
        for i in range(mid):
            # len(s) - 1 - i 是从右往左数第 i 个位置，i 递增时两指针自然向中间靠拢
            if s[i] != s[len(s) - 1 - i]:
                return False
        # 全部对称，是回文数；mid = 0 的单个数字不进循环，直接返回 True
        return True
